def transform(grid):
    # Compare the matching cells in panels on either side of the divider.
    # Same-background pair -> 3; a marked cell on either side -> 0.
    out = []
    for row in grid:
        divider = next(i for i, v in enumerate(row) if v == 7 or v == 4)
        left, right = row[:divider], row[divider+1:]
        out.append([3 if a == (0 if 7 in row else 9) and b == (0 if 7 in row else 5) else 0
                    for a, b in zip(left, right)])
    return out

